#ifdef BN_ENABLE_CUDA
typedef struct {int rows,cols,width,calls,fail_row;} RawRowsTest;
static int raw_rows_test_read(void *ctx,int row,int count,void *out,size_t capacity){RawRowsTest*s=ctx;assert(row==s->calls*32&&capacity>=(size_t)count*s->cols*s->width);s->calls++;if(row==s->fail_row)return -1;unsigned char*b=out;for(size_t i=0;i<(size_t)count*s->cols*s->width;i++)b[i]=(unsigned char)(((size_t)row*s->cols*s->width+i)*37+11);return 0;}
static void run_raw_rows_reference(BnGPUBackend*g){assert(g->buffer_create_raw_rows);const int types[]={BN_GGUF_TENSOR_F16,BN_GGUF_TENSOR_BF16,BN_GGUF_TENSOR_F32};size_t checked=0;BnCudaWeightPoolStats before,after;assert(!bn_gpu_cuda_weight_pool_stats(g,&before));for(int t=0;t<3;t++){RawRowsTest source={35,67,t==2?4:2,0,-1};size_t bytes=(size_t)source.rows*source.cols*source.width,tile=(size_t)32*source.cols*source.width;BnGPURawRowsPlan p={types[t],35,67,bytes,tile,&source,raw_rows_test_read};p.device_budget_bytes--;assert(!g->buffer_create_raw_rows(g->ctx,&p)&&!source.calls);p.device_budget_bytes++;p.host_budget_bytes--;assert(!g->buffer_create_raw_rows(g->ctx,&p)&&!source.calls);p.host_budget_bytes++;void*w=g->buffer_create_raw_rows(g->ctx,&p);assert(w&&source.calls==2);unsigned char*out=malloc(bytes+2);assert(out);memset(out,0xa5,bytes+2);assert(bn_gpu_cuda_read_raw_rows(g,w,out+1,bytes-1)==-1);for(size_t i=0;i<bytes+2;i++)assert(out[i]==0xa5);BnGPUBackend wrong=*g;int dummy;wrong.ctx=&dummy;assert(bn_gpu_cuda_read_raw_rows(&wrong,w,out+1,bytes)==-1);assert(!bn_gpu_cuda_read_raw_rows(g,w,out+1,bytes)&&out[0]==0xa5&&out[bytes+1]==0xa5);for(size_t i=0;i<bytes;i++)assert(out[i+1]==(unsigned char)(i*37+11));float x[67]={0},y[35]={0};assert(g->matvec(g->ctx,y,w,x,35,67,types[t])==-1);g->buffer_destroy(g->ctx,w);free(out);checked+=bytes;source.calls=0;source.fail_row=32;assert(!g->buffer_create_raw_rows(g->ctx,&p)&&source.calls==2);source.calls=0;source.fail_row=-1;w=g->buffer_create_raw_rows(g->ctx,&p);assert(w);g->buffer_destroy(g->ctx,w);}assert(!bn_gpu_cuda_weight_pool_stats(g,&after)&&before.idle_bytes==after.idle_bytes&&before.idle_entries==after.idle_entries);printf("CUDA raw scalar row ownership/bits/budgets/rollback PASSED: %zu bytes\n",checked);}
#endif
